using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace McpServer;

/// <summary>
/// MCP tools that wrap the Open-Meteo weather REST API.
/// The SDK discovers tools by scanning for [McpServerToolType] on the class
/// and [McpServerTool] on each public method.
/// </summary>
[McpServerToolType]
public static class WeatherTools
{
    [McpServerTool, Description("Get current weather for a location by latitude and longitude.")]
    public static async Task<string> GetCurrentWeather(
        HttpClient httpClient,
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        var url = $"https://api.open-meteo.com/v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&current=temperature_2m,wind_speed_10m";

        var response = await httpClient.GetFromJsonAsync<WeatherResponse>(url);

        if (response?.Current is null)
            return "Unable to retrieve weather data.";

        var c = response.Current;
        return $"Temperature: {c.Temperature}°C, Wind speed: {c.WindSpeed} km/h";
    }

    [McpServerTool, Description("Get a multi-day weather forecast for a location.")]
    public static async Task<string> GetForecast(
        HttpClient httpClient,
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude,
        [Description("Number of forecast days (1-16)")] int days = 7)
    {
        days = Math.Clamp(days, 1, 16);

        var url = $"https://api.open-meteo.com/v1/forecast?latitude={latitude}&longitude={longitude}"
                + $"&daily=temperature_2m_max,temperature_2m_min&forecast_days={days}";

        var response = await httpClient.GetFromJsonAsync<ForecastResponse>(url);

        if (response?.Daily is null)
            return "Unable to retrieve forecast data.";

        var lines = response.Daily.Time
            .Select((date, i) =>
                $"{date}: {response.Daily.MinTemp[i]}°C – {response.Daily.MaxTemp[i]}°C")
            .ToList();

        return string.Join('\n', lines);
    }
}

// DTOs for Open-Meteo JSON responses

public record WeatherResponse(
    [property: JsonPropertyName("current")] CurrentWeather? Current);

public record CurrentWeather(
    [property: JsonPropertyName("temperature_2m")] double Temperature,
    [property: JsonPropertyName("wind_speed_10m")] double WindSpeed);

public record ForecastResponse(
    [property: JsonPropertyName("daily")] DailyForecast? Daily);

public record DailyForecast(
    [property: JsonPropertyName("time")] string[] Time,
    [property: JsonPropertyName("temperature_2m_max")] double[] MaxTemp,
    [property: JsonPropertyName("temperature_2m_min")] double[] MinTemp);

